//! What the code generated by `#[scheduling]` calls. Not a public API: the items are reachable
//! as `oxbloom_tasks::__private` only so that the generated code can name them.

use std::fmt;

use crate::task::{BoxFuture, Task};
use crate::trigger::{Trigger, TriggerError, Zone, parse_duration};

/// The trigger of one `#[scheduled]` method, as the string literals of its attribute.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum Spec {
    /// `cron = ".."`, with `zone = ".."` when given.
    Cron(&'static str, Option<&'static str>),
    /// `fixed_rate = ".."`.
    FixedRate(&'static str),
    /// `fixed_delay = ".."`.
    FixedDelay(&'static str),
}

impl Spec {
    /// Parses the literals into a trigger, or names the key whose value is invalid.
    fn trigger(self) -> Result<Trigger, (&'static str, TriggerError)> {
        let duration = |key, text| parse_duration(text).map_err(|error| (key, error));
        match self {
            Spec::Cron(expression, zone) => {
                let zone = match zone {
                    Some(name) => Zone::parse(name).map_err(|error| ("zone", error))?,
                    None => Zone::Utc,
                };
                Trigger::cron(expression, zone).map_err(|error| ("cron", error))
            }
            Spec::FixedRate(text) => Trigger::fixed_rate(duration("fixed_rate", text)?)
                .map_err(|error| ("fixed_rate", error)),
            Spec::FixedDelay(text) => Trigger::fixed_delay(duration("fixed_delay", text)?)
                .map_err(|error| ("fixed_delay", error)),
        }
    }
}

/// Builds the task of one `#[scheduled]` method. A literal that does not parse gives
/// [`Task::invalid`] with its key, so the scheduler refuses to start and names both.
pub fn task<F>(name: String, spec: Spec, initial_delay: Option<&'static str>, run: F) -> Task
where
    F: Fn() -> BoxFuture<'static, Result<(), String>> + Send + Sync + 'static,
{
    let delay = initial_delay
        .map(parse_duration)
        .transpose()
        .map_err(|error| ("initial_delay", error));
    match (spec.trigger(), delay) {
        (Err((key, error)), _) | (Ok(_), Err((key, error))) => Task::invalid(name, key, error),
        (Ok(trigger), Ok(delay)) => {
            let task = Task::new(name, trigger, run);
            match delay {
                Some(delay) => task.initial_delay(delay),
                None => task,
            }
        }
    }
}

/// Runs the body of a plain `fn` method on tokio's blocking pool. A panic in it is raised
/// again in the returned future, so the scheduler records the run as panicked.
pub fn blocking<F>(body: F) -> BoxFuture<'static, Result<(), String>>
where
    F: FnOnce() -> Result<(), String> + Send + 'static,
{
    Box::pin(async move {
        match tokio::task::spawn_blocking(body).await {
            Ok(result) => result,
            Err(error) if error.is_panic() => std::panic::resume_unwind(error.into_panic()),
            Err(_) => Err("the blocking task was cancelled".to_owned()),
        }
    })
}

/// The return types a `#[scheduled]` method may have: `()` and `Result<(), E>` where
/// `E: Display`.
pub trait RunResult {
    /// The outcome of the run, with the error as its [`Display`](fmt::Display) string.
    fn into_run_result(self) -> Result<(), String>;
}

impl RunResult for () {
    fn into_run_result(self) -> Result<(), String> {
        Ok(())
    }
}

impl<E: fmt::Display> RunResult for Result<(), E> {
    fn into_run_result(self) -> Result<(), String> {
        self.map_err(|error| error.to_string())
    }
}
